130				return m, nil
131			}
132	
133		case tea.WindowSizeMsg:
134			m.width = msg.Width
135			m.height = msg.Height
136			m.sty = newActivityStylesWithWidth(m.width, m.useColor)
137			if m.stats != nil {
138				m = m.withViewport()
139			}
140			return m, nil
141	
142		case spinner.TickMsg:
143			if m.loading {
144				var cmd tea.Cmd
145				m.spinner, cmd = m.spinner.Update(msg)
146				return m, cmd
147			}
148		}
149	
150		if m.ready {
151			var cmd tea.Cmd
152			m.viewport, cmd = m.viewport.Update(msg)
153			return m, cmd
154		}
155	
156		return m, nil
157	}
158	
159	func (m activityModel) withViewport() activityModel {
160		headerHeight := m.headerLineCount()
161		vpHeight := m.height - headerHeight - 1
162		if vpHeight < 1 {
163			vpHeight = 1
164		}
165	
166		if !m.ready {
167			m.viewport = viewport.New(viewport.WithWidth(m.width), viewport.WithHeight(vpHeight))
168			m.ready = true
169		} else {
170			m.viewport.SetWidth(m.width)
171			m.viewport.SetHeight(vpHeight)
172		}
173		m.viewport.SetContent(m.renderCommits())
174		return m
175	}
176	
177	func (m activityModel) View() tea.View {
178		v := tea.View{AltScreen: true}
179		if m.loadErr != nil {
180			v.SetContent(fmt.Sprintf("\n  Failed to load activity: %s\n\n  Press q to quit.\n", m.loadErr))
181			return v
