186			return v
187		}
188	
189		if !m.ready {
190			return v
191		}
192	
193		var b strings.Builder
194		b.WriteString(m.renderHeader())
195		b.WriteString(m.viewport.View())
196		b.WriteString("\n")
197		b.WriteString(m.renderFooter())
198		v.SetContent(b.String())
