1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"net/url"
9		"os"
10		"sort"
11		"strconv"
12		"strings"
13		"time"
14	
15		"github.com/entireio/cli/cmd/entire/cli/api"
16		"github.com/entireio/cli/cmd/entire/cli/auth"
17		"github.com/entireio/cli/cmd/entire/cli/interactive"
18		"github.com/spf13/cobra"
19		"golang.org/x/sync/errgroup"
20	)
21	
22	const (
23		agentUnknown      = "unknown"
24		dateUnknown       = "unknown"
25		activityTimeframe = "last-month"
26		activityLimit     = 1000
27	)
28	
29	// knownAgents maps normalized agent strings from the API to display IDs.
30	// Used for the commit list, where per-checkpoint agent strings are free-form.
31	// The /me/activity endpoint returns already-normalized canonical IDs.
32	var knownAgents = map[string]string{
33		"claude":     "claude",
34		"claudecode": "claude",
35		"gemini":     "gemini",
36		"geminicli":  "gemini",
37		"amp":        "amp",
38		"codex":      "codex",
39		"opencode":   "opencode",
40		"copilot":    "copilot",
41		"copilotcli": "copilot",
42		"pi":         "pi",
43		"cursor":     "cursor",
44		"droid":      "droid",
45		"kiro":       "kiro",
46	}
47	
48	func newActivityCmd() *cobra.Command {
49		cmd := &cobra.Command{
50			Use:   "activity",
51			Short: "Show your activity overview",
52			Long:  "Display your activity overview, repository breakdown, and recent commits from entire.io",
53			RunE: func(cmd *cobra.Command, _ []string) error {
54				return runActivity(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr())
55			},
56		}
57		return cmd
58	}
59	
60	func runActivity(ctx context.Context, w, errW io.Writer) error {
61		client, err := NewAuthenticatedAPIClient(ctx, false)
62		if err != nil {
63			// Ctrl+C during the keyring read or STS exchange surfaces as
64			// context.Canceled / DeadlineExceeded. Silence it to match the
65			// codebase convention (clean.go, explain.go, explain_export.go) —
66			// printing "context canceled" at a user who just hit Ctrl+C is
67			// noise, not diagnostic.
68			if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
69				return NewSilentError(err)
70			}
71			// Only the "no core token in keyring" sentinel gets the friendly
72			// login hint. Other failures (STS exchange rejected, network
73			// error, malformed env config) used to be swallowed under the
74			// same hint, which sent users on wild goose chases trying to
75			// "re-login" their way out of unrelated server-side problems.
76			if errors.Is(err, auth.ErrNotLoggedIn) {
77				fmt.Fprintln(errW, "Not logged in. Run 'entire login' to authenticate.")
78				return NewSilentError(err)
79			}
80			return err
81		}
82	
83		// Non-interactive fallback: piped output or accessibility mode
84		if !interactive.IsTerminalWriter(w) || IsAccessibleMode() {
85			return runActivityStatic(ctx, w, client)
86		}
87	
88		return runActivityTUI(ctx, client)
89	}
90	
91	func runActivityStatic(ctx context.Context, w io.Writer, client *api.Client) error {
92		activity, commits, err := fetchActivityData(ctx, client)
93		if err != nil {
94			return err
95		}
96	
97		stats := contributionStats{
98			Tasks:         activity.Stats.Tasks,
99			Throughput:    activity.Stats.Throughput,
100			Iteration:     activity.Stats.Iteration,
101			ContinuityH:   activity.Stats.ContinuityHours,
102			Streak:        activity.Stats.LifetimeStreak,
103			CurrentStreak: activity.Stats.LifetimeCurrentStreak,
104		}
105		days := groupCommitsByDay(commits)
106	
107		sty := newActivityStyles(w)
108		renderActivity(w, sty, stats, activity.Repos, activity.HourlyContributions, days)
109		return nil
110	}
111	
112	// fetchActivityData fetches aggregated activity and commits concurrently.
113	func fetchActivityData(ctx context.Context, client *api.Client) (*userActivityResponse, []userCommit, error) {
114		var activity *userActivityResponse
115		var commits []userCommit
116	
117		g, gCtx := errgroup.WithContext(ctx)
118		g.Go(func() error {
119			var err error
120			activity, err = fetchActivity(gCtx, client)
121			return err
122		})
123		g.Go(func() error {
124			var err error
125			commits, err = fetchCommits(gCtx, client)
126			return err
127		})
128		if err := g.Wait(); err != nil {
129			return nil, nil, fmt.Errorf("fetch activity: %w", err)
130		}
131		return activity, commits, nil
132	}
133	
134	func fetchActivity(ctx context.Context, client *api.Client) (*userActivityResponse, error) {
135		q := url.Values{}
136		q.Set("timezone", detectTimezone())
137		q.Set("timeframe", activityTimeframe)
138		q.Set("limit", strconv.Itoa(activityLimit))
139		path := "/api/v1/me/activity?" + q.Encode()
140	
141		resp, err := client.Get(ctx, path)
142		if err != nil {
143			return nil, fmt.Errorf("GET activity: %w", err)
144		}
145		defer resp.Body.Close()
146	
147		if err := api.CheckResponse(resp); err != nil {
148			return nil, fmt.Errorf("activity response: %w", err)
149		}
150	
151		var result userActivityResponse
152		if err := api.DecodeJSON(resp, &result); err != nil {
153			return nil, fmt.Errorf("decode activity: %w", err)
154		}
155		return &result, nil
156	}
157	
158	func fetchCommits(ctx context.Context, client *api.Client) ([]userCommit, error) {
159		path := fmt.Sprintf("/api/v1/me/commits?timeframe=%s&limit=%d", activityTimeframe, activityLimit)
160		resp, err := client.Get(ctx, path)
161		if err != nil {
162			return nil, fmt.Errorf("GET commits: %w", err)
163		}
164		defer resp.Body.Close()
165	
166		if err := api.CheckResponse(resp); err != nil {
167			return nil, fmt.Errorf("commits response: %w", err)
168		}
169	
170		var result userCommitsResponse
171		if err := api.DecodeJSON(resp, &result); err != nil {
172			return nil, fmt.Errorf("decode commits: %w", err)
173		}
174		return result.Commits, nil
175	}
176	
177	// detectTimezone returns a best-effort timezone name for the current host.
178	// Order: $TZ → /etc/localtime symlink → time.Local → "UTC" as last resort.
179	// A candidate that fails normalization is skipped (not forwarded, not coerced
180	// to UTC), so a bogus $TZ on a correctly-configured box still yields the
181	// system timezone from /etc/localtime. The server is the canonical authority
182	// for what counts as a valid zone and falls back to UTC for anything it
183	// doesn't recognize, so we only do enough validation to avoid sending
184	// obvious garbage (paths, POSIX forms Go can't load, the "Local" sentinel).
185	func detectTimezone() string {
186		if tz := normalizeTimezone(os.Getenv("TZ")); tz != "" {
187			return tz
188		}
189		if link, err := os.Readlink("/etc/localtime"); err == nil {
190			if tz := normalizeTimezone(link); tz != "" {
191				return tz
192			}
193		}
194		if tz := normalizeTimezone(time.Local.String()); tz != "" {
195			return tz
196		}
197		return "UTC"
198	}
199	
200	// normalizeTimezone returns a name Go can load as a time zone, or "" if the
201	// input can't be resolved. It strips the POSIX ":" prefix and zoneinfo path
202	// prefix, then requires time.LoadLocation to succeed.
203	//
204	// This is not strict IANA-only validation: Go's LoadLocation accepts legacy
205	// aliases like EST5EDT, GMT0, and PST8PDT in addition to Area/Location
206	// names. Those may or may not be canonically understood by the server — if
207	// the server doesn't recognize one, it falls back to UTC on its end. We
208	// accept that mild mis-bucketing risk as the price of a simple check that
209	// catches the common failure modes (paths, unknown POSIX forms like UTC0,
210	// typos, the "Local" sentinel).
211	func normalizeTimezone(raw string) string {
212		name := strings.TrimPrefix(raw, ":")
213		const marker = "/zoneinfo/"
214		if idx := strings.LastIndex(name, marker); idx >= 0 {
215			name = name[idx+len(marker):]
216		}
217		if name == "" || name == "Local" {
218			return ""
219		}
220		if _, err := time.LoadLocation(name); err != nil {
221			return ""
222		}
223		return name
224	}
225	
226	func groupCommitsByDay(commits []userCommit) []commitDay {
227		byDate := make(map[string][]userCommit)
228		var dateOrder []string
229	
230		for _, c := range commits {
231			date := dateUnknown
232			if c.CommitDate != nil {
233				if t, err := parseFlexibleTime(*c.CommitDate); err == nil {
234					date = t.Local().Format("2006-01-02")
235				}
236			}
237			if _, exists := byDate[date]; !exists {
238				dateOrder = append(dateOrder, date)
239			}
240			byDate[date] = append(byDate[date], c)
241		}
242	
243		// Sort dates newest first, with unknown dates pushed to the end
244		sort.Slice(dateOrder, func(i, j int) bool {
245			if dateOrder[i] == dateUnknown {
246				return false
247			}
248			if dateOrder[j] == dateUnknown {
249				return true
250			}
251			return dateOrder[i] > dateOrder[j]
252		})
253	
254		result := make([]commitDay, 0, len(dateOrder))
255		for _, d := range dateOrder {
256			result = append(result, commitDay{Date: d, Commits: byDate[d]})
257		}
258		return result
259	}
260	
261	func normalizeAgentString(s string) string {
262		if s == "" {
263			return agentUnknown
264		}
265	
266		var sb strings.Builder
267		for _, r := range s {
268			if r == ' ' || r == '-' || r == '_' {
269				continue
270			}
271			if r >= 'A' && r <= 'Z' {
272				sb.WriteByte(byte(r + 32))
273			} else {
274				sb.WriteRune(r)
275			}
276		}
277		lower := sb.String()
278	
279		if id, ok := knownAgents[lower]; ok {
280			return id
281		}
282	
283		for _, suffix := range []string{"code", "cli"} {
284			if len(lower) > len(suffix) && lower[len(lower)-len(suffix):] == suffix {
285				if id, ok := knownAgents[lower[:len(lower)-len(suffix)]]; ok {
286					return id
287				}
288			}
289		}
290	
291		if strings.HasPrefix(lower, "factoryaidroid") {
292			return "droid"
293		}
294	
295		return agentUnknown
296	}
297	
298	// parseFlexibleTime tries RFC3339, then RFC3339Nano.
299	func parseFlexibleTime(s string) (time.Time, error) {
300		t, err := time.Parse(time.RFC3339, s)
301		if err != nil {
302			t, err = time.Parse(time.RFC3339Nano, s)
303			if err != nil {
304				return time.Time{}, fmt.Errorf("parse time %q: %w", s, err)
305			}
306		}
307		return t, nil
308	}
