// sessionLastActivity returns the most recent timestamp for a session, used
// to order the overview's session list.
func sessionLastActivity(s *strategy.SessionState) time.Time {
	if s.LastInteractionTime != nil {
		return *s.LastInteractionTime
	}
	if s.EndedAt != nil {
		return *s.EndedAt
	}
	return s.StartedAt
}

