)

const defaultOverviewLimit = 5

func newOverviewCmd() *cobra.Command {
	var opts overviewOptions
	var insecureHTTPAuth bool

	cmd := &cobra.Command{
		Use:   "overview",
		Short: "Show recent sessions, checkpoints, and trails for this repository",
		Long: `Show a dashboard of recent work in the current repository: agent sessions,
checkpoints, and trails.

Sessions and checkpoints are read from local repository state. Trails are
fetched from entire.io and require login; when unavailable, the trails
section degrades to a hint without failing the command.

Interactive mode (default on a terminal):
  ↑/↓, j/k  move between rows
  tab       jump to the next section
  enter     expand a session or checkpoint inline; open a trail in the browser
  r         show the resume command for the selected session
  q         quit

Examples:
  entire overview            Interactive dashboard
  entire overview --json     Machine-readable output
  entire overview -n 10      Show up to 10 rows per section`,
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if _, err := paths.WorktreeRoot(cmd.Context()); err != nil {
				cmd.SilenceUsage = true
				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run 'entire overview' from within a git repository.")
				return NewSilentError(errors.New("not a git repository"))
			}
			if opts.Limit <= 0 {
				return errors.New("limit must be greater than 0")
			}
			opts.InsecureHTTP = insecureHTTPAuth
			return runOverview(cmd.Context(), cmd.OutOrStdout(), opts)
		},
	}

	cmd.Flags().BoolVar(&opts.JSON, "json", false, "Output as JSON")
	cmd.Flags().IntVarP(&opts.Limit, "limit", "n", defaultOverviewLimit, "Maximum number of rows per section")
	cmd.Flags().BoolVar(&insecureHTTPAuth, "insecure-http-auth", false,
		"Allow API calls over plain HTTP (insecure, for local development only)")
	if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
		panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
	}

	return cmd
}

func runOverview(ctx context.Context, w io.Writer, opts overviewOptions) error {
	if opts.JSON {
		data, err := fetchOverviewData(ctx, opts)
		if err != nil {
			return err
		}
		return writeOverviewJSON(w, data, opts.Limit)
	}

	if !interactive.IsTerminalWriter(w) || IsAccessibleMode() {
		data, err := fetchOverviewData(ctx, opts)
		if err != nil {
			return err
		}
		sty := newStatusStyles(w)
		renderOverview(w, sty, data, opts.Limit)
		return nil
	}

	return runOverviewTUI(ctx, w, opts)
}

// fetchOverviewData gathers all three sections concurrently. A trails failure
// is captured in TrailsErr instead of failing the fetch — sessions and
// checkpoints are local and must not be blocked by network or auth problems.
func fetchOverviewData(ctx context.Context, opts overviewOptions) (*overviewData, error) {
	data := &overviewData{}

	if branch, err := GetCurrentBranch(ctx); err == nil {
		data.Branch = branch
	}
	forge, owner, repoName, remoteErr := resolveTrailRemote(ctx)
	if remoteErr == nil {
		data.Forge, data.Owner, data.RepoName = forge, owner, repoName
		data.RepoLabel = owner + "/" + repoName
	} else if root, err := paths.WorktreeRoot(ctx); err == nil {
		data.RepoLabel = filepath.Base(root)
	}

	g, gCtx := errgroup.WithContext(ctx)
	g.Go(func() error {
		states, err := strategy.ListSessionStates(gCtx)
		if err != nil {
			return fmt.Errorf("failed to list sessions: %w", err)
		}
		data.Sessions = sortSessionsForOverview(states)
		return nil
	})
	g.Go(func() error {
		checkpoints, err := strategy.ListCheckpoints(gCtx)
		if err != nil {
			return fmt.Errorf("failed to list checkpoints: %w", err)
		}
		sort.Slice(checkpoints, func(i, j int) bool {
			return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
		})
		data.Checkpoints = checkpoints
		return nil
	})
	g.Go(func() error {
		data.Trails, data.TrailsErr = fetchOverviewTrails(gCtx, opts.InsecureHTTP, remoteErr, forge, owner, repoName)
		return nil
	})
	if err := g.Wait(); err != nil {
		return nil, err
	}
	return data, nil
}

// sortSessionsForOverview drops nil entries and orders sessions by most
// recent activity (last interaction, then end time, then start time).
func sortSessionsForOverview(states []*strategy.SessionState) []*strategy.SessionState {
	sessions := make([]*strategy.SessionState, 0, len(states))
	for _, s := range states {
		if s != nil {
			sessions = append(sessions, s)
		}
	}
	sort.Slice(sessions, func(i, j int) bool {
		return sessionLastActivity(sessions[i]).After(sessionLastActivity(sessions[j]))
	})
	return sessions
}

// fetchOverviewTrails fetches trails for the resolved forge remote, sorted by
// most recently updated. All failures (unsupported remote, not logged in,
// network) are returned as the error for the caller to render as a hint.
func fetchOverviewTrails(ctx context.Context, insecureHTTP bool, remoteErr error, forge, owner, repoName string) ([]*trail.Metadata, error) {
	if remoteErr != nil {
		return nil, remoteErr
	}
	client, err := NewAuthenticatedAPIClient(ctx, insecureHTTP)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %w", err)
	}
	trails, err := fetchTrailMetadata(ctx, client, forge, owner, repoName)
	if err != nil {
		return nil, err
	}
	sort.Slice(trails, func(i, j int) bool {
		return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
	})
	return trails, nil
}

// overviewTrailHint maps a trails fetch failure to a one-line user hint.
func overviewTrailHint(err error) string {
	if errors.Is(err, auth.ErrNotLoggedIn) {
		return "Run 'entire login' to see trails."
	}
	return "Trails unavailable: " + err.Error()
}

func writeOverviewJSON(w io.Writer, data *overviewData, limit int) error {
	out := overviewJSON{
		Repo:        data.RepoLabel,
		Branch:      data.Branch,
		Sessions:    make([]sessionInfoJSON, 0, limit),
		Checkpoints: make([]overviewCheckpointJSON, 0, limit),
		Trails:      []*trail.Metadata{},
	}
	for _, s := range limitSlice(data.Sessions, limit) {
		out.Sessions = append(out.Sessions, buildSessionInfoJSON(s, sessionPhaseLabel(s)))
	}
	for _, c := range limitSlice(data.Checkpoints, limit) {
		out.Checkpoints = append(out.Checkpoints, overviewCheckpointJSON{
			CheckpointID: c.CheckpointID.String(),
			SessionID:    c.SessionID,
			SessionCount: c.SessionCount,
			CreatedAt:    c.CreatedAt,
			Agent:        string(c.Agent),
			FilesTouched: c.FilesTouched,
			IsTask:       c.IsTask,
		})
	}
	if data.TrailsErr != nil {
		out.TrailsError = data.TrailsErr.Error()
	} else {
		out.Trails = limitSlice(data.Trails, limit)
	}

	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	if err := enc.Encode(out); err != nil {
		return fmt.Errorf("failed to encode overview: %w", err)
	}
	return nil
}

// limitSlice returns at most limit elements of s without copying.
func limitSlice[T any](s []T, limit int) []T {
	if len(s) > limit {
		return s[:limit]
	}
	return s
}

