type overviewModel struct {
	ctx  context.Context //nolint:containedctx // bubbletea fetch Cmds need the command context
	opts overviewOptions

	data    *overviewData
	loading bool
	loadErr error
	spinner spinner.Model

	rows      []overviewRowRef
	cursor    int
