	if err != nil {
		return overviewErrMsg{err: err}
	}
	return overviewDataMsg{data: data}
}

func (m overviewModel) Init() tea.Cmd {
	return tea.Batch(m.spinner.Tick, m.fetchData)
}

func (m overviewModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case overviewDataMsg:
		m.loading = false
		m.data = msg.data
		m.rows = buildOverviewRows(msg.data, m.opts.Limit)
		if m.width > 0 {
			m = m.withViewport()
		}
		return m, nil

	case overviewErrMsg:
		m.loading = false
		m.loadErr = msg.err
		return m, nil

	case overviewCheckpointDetailMsg:
		if st, ok := m.cpDetails[msg.id]; ok {
			st.loading = false
			st.summary = msg.summary
			st.err = msg.err
		}
		if m.ready {
			m = m.refreshContent()
		}
		return m, nil

	case overviewBrowserMsg:
		if msg.err != nil {
			m.status = "Could not open browser: " + msg.url
		} else {
			m.status = "Opened " + msg.url
		}
		return m, nil

	case tea.KeyPressMsg:
		return m.handleKey(msg)

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.sty = newStatusStylesWithWidth(m.useColor, m.width)
		if m.data != nil {
			m = m.withViewport()
		}
		return m, nil

	case spinner.TickMsg:
		if m.loading {
			var cmd tea.Cmd
			m.spinner, cmd = m.spinner.Update(msg)
			return m, cmd
		}
	}

	if m.ready {
		var cmd tea.Cmd
		m.viewport, cmd = m.viewport.Update(msg)
		return m, cmd
	}
	return m, nil
}

func (m overviewModel) handleKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch {
	case key.Matches(msg, keys.Quit) || key.Matches(msg, keys.Back):
		return m, tea.Quit

	case key.Matches(msg, keys.Up):
		if m.cursor > 0 {
			m.cursor--
			m.status = ""
			m = m.refreshContent()
		}
		return m, nil

	case key.Matches(msg, keys.Down):
		if m.cursor < len(m.rows)-1 {
			m.cursor++
			m.status = ""
			m = m.refreshContent()
		}
		return m, nil

	case key.Matches(msg, overviewKeys.NextSec):
		if next := nextSectionRow(m.rows, m.cursor); next >= 0 {
			m.cursor = next
			m.status = ""
			m = m.refreshContent()
		}
		return m, nil

	case key.Matches(msg, keys.Home):
		if len(m.rows) > 0 {
			m.cursor = 0
			m = m.refreshContent()
		}
		return m, nil

	case key.Matches(msg, keys.End):
		if len(m.rows) > 0 {
			m.cursor = len(m.rows) - 1
			m = m.refreshContent()
		}
		return m, nil

	case key.Matches(msg, keys.Confirm):
		return m.handleSelect()

	case key.Matches(msg, overviewKeys.Resume):
		if row, ok := m.currentRow(); ok && row.section == overviewSectionSessions {
			m.resumeFor = m.data.Sessions[row.index]
			return m, tea.Quit
		}
		return m, nil
	}

	if m.ready {
		var cmd tea.Cmd
		m.viewport, cmd = m.viewport.Update(msg)
		return m, cmd
	}
	return m, nil
}

// handleSelect runs the enter action for the current row: toggle inline
// detail for sessions and checkpoints, open the browser for trails.
func (m overviewModel) handleSelect() (tea.Model, tea.Cmd) {
	row, ok := m.currentRow()
	if !ok {
		return m, nil
	}

	switch row.section {
	case overviewSectionSessions:
		m.expanded[m.cursor] = !m.expanded[m.cursor]
		m = m.refreshContent()
		return m, nil

	case overviewSectionCheckpoints:
		m.expanded[m.cursor] = !m.expanded[m.cursor]
		cp := m.data.Checkpoints[row.index]
		var cmd tea.Cmd
		if m.expanded[m.cursor] {
			if _, loaded := m.cpDetails[cp.CheckpointID]; !loaded {
				m.cpDetails[cp.CheckpointID] = &overviewCheckpointDetailState{loading: true}
				cmd = m.loadCheckpointDetail(cp.CheckpointID)
			}
		}
		m = m.refreshContent()
		return m, cmd

	case overviewSectionTrails:
		t := m.data.Trails[row.index]
		url := trailWebURL(api.BaseURL(), m.data.Forge, m.data.Owner, m.data.RepoName, t.Number)
		m.status = "Opening " + url + "…"
		return m, func() tea.Msg {
			return overviewBrowserMsg{url: url, err: openBrowser(m.ctx, url)}
		}
	}
	return m, nil
}

// loadCheckpointDetail lazily reads a checkpoint's committed metadata.
func (m overviewModel) loadCheckpointDetail(cpID id.CheckpointID) tea.Cmd {
	ctx := m.ctx
	return func() tea.Msg {
		summary, err := readCheckpointSummaryByID(ctx, cpID)
		return overviewCheckpointDetailMsg{id: cpID, summary: summary, err: err}
	}
}

// readCheckpointSummaryByID reads the committed metadata for one checkpoint.
// Mirrors the explain lookup's store wiring (including the fetch-pack blob
// fetcher for partial clones) without listing every checkpoint.
func readCheckpointSummaryByID(ctx context.Context, cpID id.CheckpointID) (*checkpoint.CheckpointSummary, error) {
	repo, err := openRepository(ctx)
	if err != nil {
		return nil, fmt.Errorf("not a git repository: %w", err)
	}
	defer func() { _ = repo.Close() }()

	store := checkpoint.NewGitStore(repo, checkpoint.ResolveCommittedRefs(ctx))
	store.SetBlobFetcher(FetchBlobsByHash)
	summary, err := checkpoint.ReadCommittedCheckpoint(ctx, store, cpID)
	if err != nil {
		return nil, fmt.Errorf("failed to read checkpoint: %w", err)
	}
	return summary, nil
}

func (m overviewModel) currentRow() (overviewRowRef, bool) {
	if m.cursor < 0 || m.cursor >= len(m.rows) {
		return overviewRowRef{}, false
	}
	return m.rows[m.cursor], true
}

// buildOverviewRows flattens the limited section slices into cursor rows.
func buildOverviewRows(data *overviewData, limit int) []overviewRowRef {
	var rows []overviewRowRef
	for i := range limitSlice(data.Sessions, limit) {
		rows = append(rows, overviewRowRef{section: overviewSectionSessions, index: i})
	}
	for i := range limitSlice(data.Checkpoints, limit) {
		rows = append(rows, overviewRowRef{section: overviewSectionCheckpoints, index: i})
	}
	if data.TrailsErr == nil {
		for i := range limitSlice(data.Trails, limit) {
			rows = append(rows, overviewRowRef{section: overviewSectionTrails, index: i})
		}
	}
	return rows
}

// nextSectionRow returns the index of the first row of the section after the
// cursor's, cycling back to the first section. Returns -1 when there is
// nowhere to jump (zero or one section with rows).
func nextSectionRow(rows []overviewRowRef, cursor int) int {
	if len(rows) == 0 {
		return -1
	}
	current := rows[0].section
	if cursor >= 0 && cursor < len(rows) {
		current = rows[cursor].section
	}
	// First row of each section, in row order.
	firstOf := make(map[overviewSection]int)
	var order []overviewSection
	for i, r := range rows {
		if _, seen := firstOf[r.section]; !seen {
			firstOf[r.section] = i
			order = append(order, r.section)
		}
	}
	if len(order) < 2 {
		return -1
	}
	for i, sec := range order {
		if sec == current {
			return firstOf[order[(i+1)%len(order)]]
		}
	}
	return -1
}

func (m overviewModel) withViewport() overviewModel {
	headerHeight := strings.Count(m.renderTitle(), "\n")
	vpHeight := m.height - headerHeight - 2 // status + footer
	if vpHeight < 1 {
		vpHeight = 1
	}

	if !m.ready {
		m.viewport = viewport.New(viewport.WithWidth(m.width), viewport.WithHeight(vpHeight))
		m.ready = true
	} else {
		m.viewport.SetWidth(m.width)
		m.viewport.SetHeight(vpHeight)
	}
	return m.refreshContent()
}

// refreshContent re-renders the body into the viewport and keeps the cursor
// row visible.
func (m overviewModel) refreshContent() overviewModel {
	if !m.ready {
		return m
	}
	content, rowLines := m.renderBody()
	m.viewport.SetContent(content)
	if m.cursor >= 0 && m.cursor < len(rowLines) {
		line := rowLines[m.cursor]
		top := m.viewport.YOffset()
		bottom := top + m.viewport.Height() - 1
		switch {
		case line < top:
			m.viewport.SetYOffset(line)
		case line > bottom:
			m.viewport.SetYOffset(line - m.viewport.Height() + 1)
		}
	}
	return m
}

func (m overviewModel) View() tea.View {
	v := tea.View{AltScreen: true}
	if m.loadErr != nil {
		v.SetContent(fmt.Sprintf("\n  Failed to load overview: %s\n\n  Press q to quit.\n", m.loadErr))
		return v
	}
	if m.loading {
		v.SetContent(fmt.Sprintf("\n  %s Loading overview...\n", m.spinner.View()))
		return v
	}
	if !m.ready {
		return v
	}

	var b strings.Builder
	b.WriteString(m.renderTitle())
	b.WriteString(m.viewport.View())
	b.WriteString("\n")
	b.WriteString(m.renderStatusLine())
	b.WriteString("\n")
	b.WriteString(m.renderFooter())
	v.SetContent(b.String())
	return v
}

func (m overviewModel) renderTitle() string {
	if m.data == nil {
		return ""
	}
	return "\n" + m.sty.identityBullet("Overview", overviewHeaderLabel(m.data)) + "\n"
}

func (m overviewModel) renderStatusLine() string {
	if m.status == "" {
		return ""
	}
	return m.sty.render(m.sty.dim, "  "+m.status)
}

// renderBody renders all sections and returns the content plus, for each
// cursor row, the line index it starts at (for scroll-into-view).
func (m overviewModel) renderBody() (string, []int) {
	var b strings.Builder
	rowLines := make([]int, 0, len(m.rows))
	line := 0
	write := func(s string) {
		b.WriteString(s)
		line += strings.Count(s, "\n")
	}

	rowIdx := 0
	writeRow := func(content string, expandedDetail string) {
		cursorPrefix := "  "
		if rowIdx == m.cursor {
			cursorPrefix = m.sty.render(m.sty.agent, "▸") + " "
		}
		rowLines = append(rowLines, line)
		write(cursorPrefix + content + "\n")
		if m.expanded[rowIdx] && expandedDetail != "" {
			write(expandedDetail)
		}
		rowIdx++
	}

	// Sessions
	write(m.sty.sectionRule("Sessions", m.sty.width) + "\n")
	if len(m.data.Sessions) == 0 {
		write(m.sty.render(m.sty.dim, "  No sessions yet.") + "\n")
	}
	for _, s := range limitSlice(m.data.Sessions, m.opts.Limit) {
		detail := ""
		if m.expanded[rowIdx] {
			detail = overviewSessionDetail(m.sty, s)
		}
		writeRow(overviewSessionRow(m.sty, s), detail)
	}
	m.writeSectionFooter(write, len(m.data.Sessions), "entire session list")
	write("\n")

	// Checkpoints
	write(m.sty.sectionRule("Checkpoints", m.sty.width) + "\n")
	if len(m.data.Checkpoints) == 0 {
		write(m.sty.render(m.sty.dim, "  No checkpoints yet.") + "\n")
	}
	for _, c := range limitSlice(m.data.Checkpoints, m.opts.Limit) {
		detail := ""
		if m.expanded[rowIdx] {
			st := m.cpDetails[c.CheckpointID]
			if st == nil {
				st = &overviewCheckpointDetailState{loading: true}
			}
			detail = overviewCheckpointDetail(m.sty, c, st.summary, st.err, st.loading)
		}
		writeRow(overviewCheckpointRow(m.sty, c), detail)
	}
	m.writeSectionFooter(write, len(m.data.Checkpoints), "entire checkpoint list")
	write("\n")

	// Trails
	write(m.sty.sectionRule("Trails", m.sty.width) + "\n")
	switch {
	case m.data.TrailsErr != nil:
		write(m.sty.render(m.sty.dim, "  "+overviewTrailHint(m.data.TrailsErr)) + "\n")
	case len(m.data.Trails) == 0:
		write(m.sty.render(m.sty.dim, "  No trails yet.") + "\n")
	default:
		for _, t := range limitSlice(m.data.Trails, m.opts.Limit) {
			writeRow(overviewTrailRow(m.sty, t), "")
		}
		m.writeSectionFooter(write, len(m.data.Trails), "entire trail list")
	}

	return b.String(), rowLines
}

func (m overviewModel) writeSectionFooter(write func(string), total int, hint string) {
	if total <= m.opts.Limit {
		return
	}
	write(m.sty.render(m.sty.dim, fmt.Sprintf("  %d of %d · %s", m.opts.Limit, total, hint)) + "\n")
}

func (m overviewModel) renderFooter() string {
	if !m.sty.colorEnabled {
		return ""
	}
	helpStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
	keyStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("245")).Bold(true)
	sep := helpStyle.Render(" · ")

	parts := []string{
		keyStyle.Render("↑/↓") + helpStyle.Render(" move"),
		keyStyle.Render("tab") + helpStyle.Render(" section"),
	}
	if row, ok := m.currentRow(); ok {
		switch row.section {
		case overviewSectionSessions:
			parts = append(parts,
				keyStyle.Render("enter")+helpStyle.Render(" details"),
				keyStyle.Render("r")+helpStyle.Render(" resume"))
		case overviewSectionCheckpoints:
			parts = append(parts, keyStyle.Render("enter")+helpStyle.Render(" details"))
		case overviewSectionTrails:
			parts = append(parts, keyStyle.Render("enter")+helpStyle.Render(" open"))
		}
	}
	parts = append(parts, keyStyle.Render(keys.Quit.Help().Key)+helpStyle.Render(" "+keys.Quit.Help().Desc))

	full := strings.Join(parts, sep)
	if m.width > 0 && lipgloss.Width(full) > m.width {
		return keyStyle.Render(keys.Quit.Help().Key) + helpStyle.Render(" "+keys.Quit.Help().Desc)
	}
	return full
}

