	"github.com/entireio/cli/cmd/entire/cli/trail"
)

func plainOverviewStyles() statusStyles {
	return newStatusStylesWithWidth(false, 80)
}

func testOverviewSession(idStr string, ended bool, lastActivity time.Time) *strategy.SessionState {
	s := &strategy.SessionState{
		SessionID:           idStr,
		AgentType:           types.AgentType("claude-code"),
		StartedAt:           lastActivity.Add(-time.Hour),
		LastInteractionTime: &lastActivity,
		LastPrompt:          "Fix the stdin hang in dispatch",
	}
	if ended {
		endedAt := lastActivity
		s.EndedAt = &endedAt
	}
	return s
}

func testOverviewCheckpoint(idStr string, createdAt time.Time) strategy.CheckpointInfo {
	return strategy.CheckpointInfo{
		CheckpointID: id.CheckpointID(idStr),
		SessionID:    "sess-1",
		CreatedAt:    createdAt,
		FilesTouched: []string{"a.go", "b.go"},
		Agent:        types.AgentType("claude-code"),
	}
}

func testOverviewTrail(number int, title string, updatedAt time.Time) *trail.Metadata {
	return &trail.Metadata{
		Number:    number,
		Title:     title,
		Branch:    "feature-branch",
		Status:    trail.StatusInProgress,
		UpdatedAt: updatedAt,
	}
}

func testOverviewDataFull() *overviewData {
	now := time.Now()
	return &overviewData{
		RepoLabel:   "entireio/cli",
		Branch:      "main",
		Forge:       "gh",
		Owner:       "entireio",
		RepoName:    "cli",
		Sessions:    []*strategy.SessionState{testOverviewSession("sess-1", false, now), testOverviewSession("sess-2", true, now.Add(-time.Hour))},
		Checkpoints: []strategy.CheckpointInfo{testOverviewCheckpoint("aaaabbbbcccc", now), testOverviewCheckpoint("ddddeeeeffff", now.Add(-time.Hour))},
		Trails:      []*trail.Metadata{testOverviewTrail(12, "Add overview command", now)},
	}
}

func TestOverviewSessionRow(t *testing.T) {
	t.Parallel()
	sty := plainOverviewStyles()

	active := overviewSessionRow(sty, testOverviewSession("sess-1", false, time.Now()))
	if !strings.Contains(active, "●") {
		t.Errorf("active session row missing filled bullet: %q", active)
	}
	if !strings.Contains(active, "Fix the stdin hang in dispatch") {
		t.Errorf("session row missing prompt title: %q", active)
	}
	if !strings.Contains(active, "claude-code") {
		t.Errorf("session row missing agent: %q", active)
	}

	ended := overviewSessionRow(sty, testOverviewSession("sess-2", true, time.Now()))
	if !strings.Contains(ended, "○") {
		t.Errorf("ended session row missing hollow bullet: %q", ended)
	}
	if !strings.Contains(ended, "ended") {
		t.Errorf("ended session row missing status: %q", ended)
	}

	noPrompt := testOverviewSession("sess-3", false, time.Now())
	noPrompt.LastPrompt = ""
	row := overviewSessionRow(sty, noPrompt)
	if !strings.Contains(row, "(no prompt)") {
		t.Errorf("session row missing prompt placeholder: %q", row)
	}
}

func TestOverviewCheckpointRow(t *testing.T) {
	t.Parallel()
	sty := plainOverviewStyles()

	row := overviewCheckpointRow(sty, testOverviewCheckpoint("aaaabbbbcccc", time.Now()))
	for _, want := range []string{"aaaabbbbcccc", "2 files", "claude-code"} {
		if !strings.Contains(row, want) {
			t.Errorf("checkpoint row missing %q: %q", want, row)
		}
	}

	multi := testOverviewCheckpoint("ddddeeeeffff", time.Now())
