	if out.Sessions[0].SessionID != "sess-1" {
		t.Errorf("session id = %q", out.Sessions[0].SessionID)
	}
	if out.Checkpoints[0].CheckpointID != "aaaabbbbcccc" {
		t.Errorf("checkpoint id = %q", out.Checkpoints[0].CheckpointID)
