func TestWriteOverviewJSON_TrailsError(t *testing.T) {
	t.Parallel()

	data := testOverviewDataFull()
	data.TrailsErr = errors.New("boom")
	var buf bytes.Buffer
	if err := writeOverviewJSON(&buf, data, 5); err != nil {
		t.Fatalf("writeOverviewJSON: %v", err)
	}

	var out overviewJSON
	if err := json.Unmarshal(buf.Bytes(), &out); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	if out.TrailsError != "boom" {
		t.Errorf("trails_error = %q", out.TrailsError)
	}
	if len(out.Trails) != 0 {
		t.Errorf("trails should be empty on error, got %d", len(out.Trails))
	}
