func TestSortSessionsForOverview(t *testing.T) {
	t.Parallel()

	now := time.Now()
	older := testOverviewSession("older", true, now.Add(-2*time.Hour))
	newest := testOverviewSession("newest", false, now)
	middle := testOverviewSession("middle", false, now.Add(-time.Hour))

	sorted := sortSessionsForOverview([]*strategy.SessionState{older, nil, newest, middle})
	gotIDs := make([]string, 0, len(sorted))
	for _, s := range sorted {
		gotIDs = append(gotIDs, s.SessionID)
	}
	want := []string{"newest", "middle", "older"}
	for i := range want {
		if gotIDs[i] != want[i] {
			t.Fatalf("sorted order = %v, want %v", gotIDs, want)
		}
	}
}

func TestSessionLastActivity(t *testing.T) {
	t.Parallel()

	started := time.Date(2026, 6, 1, 10, 0, 0, 0, time.UTC)
	s := &strategy.SessionState{StartedAt: started}
	if got := sessionLastActivity(s); !got.Equal(started) {
		t.Errorf("fallback to StartedAt failed: %v", got)
	}

	ended := started.Add(time.Hour)
	s.EndedAt = &ended
	if got := sessionLastActivity(s); !got.Equal(ended) {
		t.Errorf("EndedAt precedence failed: %v", got)
	}

	interacted := started.Add(2 * time.Hour)
	s.LastInteractionTime = &interacted
	if got := sessionLastActivity(s); !got.Equal(interacted) {
		t.Errorf("LastInteractionTime precedence failed: %v", got)
	}
}

func TestTrailWebURL(t *testing.T) {
	t.Parallel()

	got := trailWebURL("https://entire.io", "gh", "entireio", "cli", 12)
	if got != "https://entire.io/gh/entireio/cli/trails/12" {
		t.Errorf("trailWebURL = %q", got)
	}

	got = trailWebURL("https://entire.io/", "gh", "entireio", "cli", 0)
	if got != "https://entire.io/gh/entireio/cli/trails" {
		t.Errorf("trailWebURL without number = %q", got)
	}
}

func TestOverviewHeaderLabel(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name string
		data overviewData
		want string
	}{
		{name: "repo and branch", data: overviewData{RepoLabel: "o/r", Branch: "main"}, want: "o/r (main)"},
		{name: "repo only", data: overviewData{RepoLabel: "o/r"}, want: "o/r"},
		{name: "branch only", data: overviewData{Branch: "main"}, want: "main"},
		{name: "neither", data: overviewData{}, want: ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			if got := overviewHeaderLabel(&tt.data); got != tt.want {
				t.Errorf("overviewHeaderLabel = %q, want %q", got, tt.want)
			}
		})
	}
}

// TestFetchOverviewData_LocalOnly verifies the local sections load from a
// fresh repo and a missing/unsupported origin remote degrades to TrailsErr
// without attempting authentication.
func TestFetchOverviewData_LocalOnly(t *testing.T) {
	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "f.txt", "init")
	testutil.GitAdd(t, tmpDir, "f.txt")
	testutil.GitCommit(t, tmpDir, "init")
	t.Chdir(tmpDir)

	data, err := fetchOverviewData(context.Background(), overviewOptions{Limit: 5})
	if err != nil {
		t.Fatalf("fetchOverviewData: %v", err)
	}

	if len(data.Sessions) != 0 {
		t.Errorf("expected no sessions, got %d", len(data.Sessions))
	}
	if len(data.Checkpoints) != 0 {
		t.Errorf("expected no checkpoints, got %d", len(data.Checkpoints))
	}
	if data.TrailsErr == nil {
		t.Error("expected TrailsErr for repo without forge remote")
	}
	if data.Branch == "" {
		t.Error("expected current branch to resolve")
	}
	if data.RepoLabel == "" {
		t.Error("expected repo label fallback to worktree dir name")
	}
}

// TestRunOverview_JSONInTempRepo exercises the command path end to end in
// JSON mode (non-TTY writers always take the static/JSON path).
func TestRunOverview_JSONInTempRepo(t *testing.T) {
	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "f.txt", "init")
	testutil.GitAdd(t, tmpDir, "f.txt")
	testutil.GitCommit(t, tmpDir, "init")
	t.Chdir(tmpDir)

	var buf bytes.Buffer
	if err := runOverview(context.Background(), &buf, overviewOptions{Limit: 5, JSON: true}); err != nil {
		t.Fatalf("runOverview: %v", err)
	}

	var out overviewJSON
	if err := json.Unmarshal(buf.Bytes(), &out); err != nil {
		t.Fatalf("output is not valid JSON: %v\n%s", err, buf.String())
	}
	if out.Sessions == nil || out.Checkpoints == nil || out.Trails == nil {
		t.Errorf("JSON arrays must be non-nil: %s", buf.String())
	}
	if out.TrailsError == "" {
		t.Error("expected trails_error for repo without forge remote")
	}
}

