package cli

import (
	"context"
	"errors"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
)

func testOverviewTUIModel(data *overviewData) overviewModel {
	m := overviewModel{
		ctx:       context.Background(),
		opts:      overviewOptions{Limit: 5},
		data:      data,
		rows:      buildOverviewRows(data, 5),
		expanded:  make(map[int]bool),
		cpDetails: make(map[id.CheckpointID]*overviewCheckpointDetailState),
		sty:       plainOverviewStyles(),
		width:     80,
		height:    24,
	}
	return m.withViewport()
}

func updateOverviewModel(t *testing.T, m overviewModel, msg tea.Msg) (overviewModel, tea.Cmd) {
	t.Helper()

	updated, cmd := m.Update(msg)
	result, ok := updated.(overviewModel)
	if !ok {
		t.Fatalf("Update returned %T, want overviewModel", updated)
	}
	return result, cmd
}

func overviewRuneKey(r rune) tea.KeyPressMsg {
	return tea.KeyPressMsg{Code: r, Text: string(r)}
}

func TestBuildOverviewRows(t *testing.T) {
	t.Parallel()

	data := testOverviewDataFull()
	rows := buildOverviewRows(data, 5)
	// 2 sessions + 2 checkpoints + 1 trail
	if len(rows) != 5 {
		t.Fatalf("rows = %d, want 5", len(rows))
	}
	if rows[0].section != overviewSectionSessions || rows[2].section != overviewSectionCheckpoints || rows[4].section != overviewSectionTrails {
		t.Errorf("unexpected section layout: %+v", rows)
	}

	// Limit applies per section.
	rows = buildOverviewRows(data, 1)
	if len(rows) != 3 {
		t.Fatalf("limited rows = %d, want 3", len(rows))
	}
}

func TestBuildOverviewRows_TrailsErrSkipsTrailRows(t *testing.T) {
	t.Parallel()

	data := testOverviewDataFull()
	data.TrailsErr = errors.New("boom")
	for _, row := range buildOverviewRows(data, 5) {
		if row.section == overviewSectionTrails {
			t.Fatal("trail rows must not be selectable when trails failed to load")
		}
	}
}

func TestNextSectionRow(t *testing.T) {
	t.Parallel()

	rows := buildOverviewRows(testOverviewDataFull(), 5)

	if got := nextSectionRow(rows, 0); got != 2 {
		t.Errorf("from sessions: next = %d, want 2 (first checkpoint)", got)
	}
	if got := nextSectionRow(rows, 2); got != 4 {
		t.Errorf("from checkpoints: next = %d, want 4 (first trail)", got)
	}
	if got := nextSectionRow(rows, 4); got != 0 {
		t.Errorf("from trails: next = %d, want 0 (cycle to sessions)", got)
	}
	if got := nextSectionRow(nil, 0); got != -1 {
		t.Errorf("empty rows: next = %d, want -1", got)
	}
}

func TestOverviewModel_CursorMoves(t *testing.T) {
	t.Parallel()

	m := testOverviewTUIModel(testOverviewDataFull())

	m, _ = updateOverviewModel(t, m, tea.KeyPressMsg{Code: tea.KeyDown})
	if m.cursor != 1 {
		t.Fatalf("cursor = %d after down, want 1", m.cursor)
	}
	m, _ = updateOverviewModel(t, m, overviewRuneKey('k'))
	if m.cursor != 0 {
		t.Fatalf("cursor = %d after k, want 0", m.cursor)
	}
	// Up at the top stays put.
	m, _ = updateOverviewModel(t, m, tea.KeyPressMsg{Code: tea.KeyUp})
	if m.cursor != 0 {
		t.Fatalf("cursor = %d after up at top, want 0", m.cursor)
	}
}

func TestOverviewModel_TabJumpsToNextSection(t *testing.T) {
	t.Parallel()

	m := testOverviewTUIModel(testOverviewDataFull())
	m, _ = updateOverviewModel(t, m, tea.KeyPressMsg{Code: tea.KeyTab})
	if row, ok := m.currentRow(); !ok || row.section != overviewSectionCheckpoints {
		t.Fatalf("after tab, cursor = %d (section %v), want first checkpoint row", m.cursor, row.section)
	}
}

func TestOverviewModel_EnterTogglesSessionDetail(t *testing.T) {
	t.Parallel()

	m := testOverviewTUIModel(testOverviewDataFull())

	m, _ = updateOverviewModel(t, m, tea.KeyPressMsg{Code: tea.KeyEnter})
	if !m.expanded[0] {
		t.Fatal("enter should expand the selected session row")
	}
	content, _ := m.renderBody()
	if !strings.Contains(content, "sess-1") {
		t.Errorf("expanded session detail missing session ID:\n%s", content)
	}

	m, _ = updateOverviewModel(t, m, tea.KeyPressMsg{Code: tea.KeyEnter})
	if m.expanded[0] {
		t.Fatal("second enter should collapse the row")
	}
}

func TestOverviewModel_EnterOnCheckpointStartsDetailLoad(t *testing.T) {
	t.Parallel()

	m := testOverviewTUIModel(testOverviewDataFull())
	m.cursor = 2 // first checkpoint row

	m, cmd := updateOverviewModel(t, m, tea.KeyPressMsg{Code: tea.KeyEnter})
	if !m.expanded[2] {
		t.Fatal("enter should expand the checkpoint row")
	}
	if cmd == nil {
		t.Fatal("enter on an unloaded checkpoint should return a load Cmd")
	}
	st := m.cpDetails[id.CheckpointID("aaaabbbbcccc")]
	if st == nil || !st.loading {
		t.Fatalf("checkpoint detail should be loading, got %+v", st)
	}

	content, _ := m.renderBody()
	if !strings.Contains(content, "loading…") {
		t.Errorf("expanded checkpoint should show loading state:\n%s", content)
	}

	// Detail arrives.
	m, _ = updateOverviewModel(t, m, overviewCheckpointDetailMsg{
		id:  id.CheckpointID("aaaabbbbcccc"),
		err: errors.New("nope"),
	})
	content, _ = m.renderBody()
	if !strings.Contains(content, "unavailable: nope") {
		t.Errorf("checkpoint detail error not rendered:\n%s", content)
	}
}

func TestOverviewModel_ResumeOnSessionQuits(t *testing.T) {
	t.Parallel()

	m := testOverviewTUIModel(testOverviewDataFull())
	m, cmd := updateOverviewModel(t, m, overviewRuneKey('r'))

	if m.resumeFor == nil || m.resumeFor.SessionID != "sess-1" {
		t.Fatalf("resumeFor = %+v, want sess-1", m.resumeFor)
	}
	if cmd == nil {
		t.Fatal("r should quit the TUI")
	}
	if _, ok := cmd().(tea.QuitMsg); !ok {
		t.Fatal("r should return tea.Quit")
	}
}

func TestOverviewModel_ResumeIgnoredOffSessionRows(t *testing.T) {
	t.Parallel()

	m := testOverviewTUIModel(testOverviewDataFull())
	m.cursor = 2 // checkpoint row
	m, cmd := updateOverviewModel(t, m, overviewRuneKey('r'))

	if m.resumeFor != nil {
		t.Fatalf("resumeFor should stay nil on checkpoint rows, got %+v", m.resumeFor)
	}
	if cmd != nil {
		t.Fatal("r on a checkpoint row should be a no-op")
	}
}

func TestOverviewModel_BrowserMsgSetsStatus(t *testing.T) {
	t.Parallel()

	m := testOverviewTUIModel(testOverviewDataFull())

	m, _ = updateOverviewModel(t, m, overviewBrowserMsg{url: "https://x", err: errors.New("no browser")})
	if !strings.Contains(m.status, "Could not open browser") {
		t.Errorf("status = %q", m.status)
	}

	m, _ = updateOverviewModel(t, m, overviewBrowserMsg{url: "https://x"})
	if !strings.Contains(m.status, "Opened https://x") {
		t.Errorf("status = %q", m.status)
	}
}

func TestOverviewModel_QuitKeys(t *testing.T) {
	t.Parallel()

	for _, k := range []tea.KeyPressMsg{overviewRuneKey('q'), {Code: tea.KeyEscape}} {
		_, cmd := updateOverviewModel(t, testOverviewTUIModel(testOverviewDataFull()), k)
		if cmd == nil {
			t.Fatal("quit key should return a command")
		}
		if _, ok := cmd().(tea.QuitMsg); !ok {
			t.Fatalf("key %v should quit", k)
		}
	}
}

func TestOverviewModel_DataMsgBuildsRows(t *testing.T) {
	t.Parallel()

	m := overviewModel{
		ctx:       context.Background(),
		opts:      overviewOptions{Limit: 5},
		loading:   true,
		expanded:  make(map[int]bool),
		cpDetails: make(map[id.CheckpointID]*overviewCheckpointDetailState),
		sty:       plainOverviewStyles(),
	}
	m, _ = updateOverviewModel(t, m, overviewDataMsg{data: testOverviewDataFull()})

	if m.loading {
		t.Fatal("data msg should clear loading")
	}
	if len(m.rows) != 5 {
		t.Fatalf("rows = %d, want 5", len(m.rows))
	}
}

