package cli

import (
	"time"

	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/trail"
)

// overviewOptions are the inputs to the overview command.
type overviewOptions struct {
	Limit        int
	JSON         bool
	InsecureHTTP bool
}

// overviewData holds everything the overview renders. Sessions and
// checkpoints are repo-local; trails come from the remote API and degrade to
// TrailsErr (rendered as a hint line) without failing the command.
type overviewData struct {
	RepoLabel string // "owner/repo" when a forge remote resolves, else worktree dir name
	Branch    string

	// Forge coordinates for building trail web URLs; empty when the origin
	// remote is not on a supported forge.
	Forge, Owner, RepoName string

	Sessions    []*strategy.SessionState // newest activity first
	Checkpoints []strategy.CheckpointInfo
	Trails      []*trail.Metadata // most recently updated first
	TrailsErr   error             // non-nil when trails could not be fetched
}

// overviewJSON is the machine-readable envelope for `entire overview --json`.
// Sessions reuse the per-session envelope from `session list --json`.
type overviewJSON struct {
	Repo        string                   `json:"repo,omitempty"`
	Branch      string                   `json:"branch,omitempty"`
	Sessions    []sessionInfoJSON        `json:"sessions"`
	Checkpoints []overviewCheckpointJSON `json:"checkpoints"`
	Trails      []*trail.Metadata        `json:"trails"`
	TrailsError string                   `json:"trails_error,omitempty"`
}

type overviewCheckpointJSON struct {
	CheckpointID string    `json:"checkpoint_id"`
	SessionID    string    `json:"session_id,omitempty"`
	SessionCount int       `json:"session_count,omitempty"`
	CreatedAt    time.Time `json:"created_at"`
	Agent        string    `json:"agent,omitempty"`
	FilesTouched []string  `json:"files_touched,omitempty"`
	IsTask       bool      `json:"is_task,omitempty"`
}

// sessionLastActivity returns the most recent timestamp for a session, used
// to order the overview's session list.
func sessionLastActivity(s *strategy.SessionState) time.Time {
	if s.LastInteractionTime != nil {
		return *s.LastInteractionTime
	}
	if s.EndedAt != nil {
		return *s.EndedAt
	}
	return s.StartedAt
}

