// fetchOverviewCheckpoints lists the current user's recent checkpoints by
// walking the current branch's commits for checkpoint trailers and keeping
// the ones whose commit was authored by the local git user. The shared
// metadata branch interleaves checkpoints from everyone who pushes it, so
// listing it directly would show teammates' work; the user's own commits are
// what tie checkpoints to them.
func fetchOverviewCheckpoints(ctx context.Context) ([]overviewCheckpoint, error) {
	repo, err := openRepository(ctx)
	if err != nil {
		return nil, fmt.Errorf("not a git repository: %w", err)
	}
	defer repo.Close()

	strategy.WarnIfMetadataDisconnected()
	store := checkpoint.NewGitStore(repo, checkpoint.ResolveCommittedRefs(ctx))
	committed, err := store.ListCommitted(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to list committed checkpoints: %w", err)
	}
	committedByID := make(map[id.CheckpointID]checkpoint.CommittedInfo, len(committed))
	for _, info := range committed {
		if !info.CheckpointID.IsEmpty() {
			committedByID[info.CheckpointID] = info
		}
	}

	_, userEmail := checkpoint.GetGitAuthorFromRepo(repo)

	head, err := repo.Head()
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return nil, nil // unborn HEAD: no commits, no checkpoints
		}
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	iter, err := repo.Log(&git.LogOptions{From: head.Hash(), Order: git.LogOrderCommitterTime})
	if err != nil {
		return nil, fmt.Errorf("failed to get commit log: %w", err)
	}
	defer iter.Close()

	var checkpoints []overviewCheckpoint
	seen := make(map[id.CheckpointID]bool)
	count := 0
	err = iter.ForEach(func(c *object.Commit) error {
		if err := ctx.Err(); err != nil {
			return err //nolint:wrapcheck // Propagating context cancellation
		}
		if count >= commitScanLimit {
			return storer.ErrStop
		}
		count++
		if cp, ok := collectOverviewCheckpoint(c, committedByID, userEmail, seen); ok {
			checkpoints = append(checkpoints, cp)
		}
		return nil
	})
	if err != nil && !errors.Is(err, storer.ErrStop) {
		return nil, fmt.Errorf("failed to walk commits: %w", err)
	}
	return checkpoints, nil
}

// collectOverviewCheckpoint joins one commit with its committed checkpoint
// metadata, returning ok=false when the commit has no checkpoint trailer, the
// checkpoint isn't in the metadata branch, it was already collected, or it
// was authored by someone else.
func collectOverviewCheckpoint(c *object.Commit, committedByID map[id.CheckpointID]checkpoint.CommittedInfo, userEmail string, seen map[id.CheckpointID]bool) (overviewCheckpoint, bool) {
	cpID, found := trailers.ParseCheckpoint(c.Message)
	if !found || seen[cpID] {
		return overviewCheckpoint{}, false
	}
	if !overviewAuthorMatches(c.Author.Email, userEmail) {
		return overviewCheckpoint{}, false
	}
	info, ok := committedByID[cpID]
	if !ok {
		return overviewCheckpoint{}, false
	}
	seen[cpID] = true

	hash := c.Hash.String()
	if len(hash) > 7 {
		hash = hash[:7]
	}
	return overviewCheckpoint{
		CommittedInfo: info,
		CommitSubject: strings.Split(c.Message, "\n")[0],
		CommitHash:    hash,
	}, true
}

// overviewAuthorMatches reports whether a commit author belongs to the
// current user. An unconfigured git identity disables filtering rather than
// hiding everything ("unknown@local" is GetGitAuthorFromRepo's fallback).
func overviewAuthorMatches(authorEmail, userEmail string) bool {
	if userEmail == "" || userEmail == "unknown@local" {
		return true
	}
	return strings.EqualFold(authorEmail, userEmail)
}

