		rows = append(rows, explainRow{Label: "details", Value: "unavailable: " + loadErr.Error()})
	case summary != nil:
		if summary.Branch != "" {
			rows = append(rows, explainRow{Label: "branch", Value: summary.Branch})
		}
		if t := totalTokens(summary.TokenUsage); t > 0 {
