		return nil
	}
	shown := files
	more := 0
	if len(shown) > overviewMaxDetailFiles {
		more = len(shown) - overviewMaxDetailFiles
		shown = shown[:overviewMaxDetailFiles]
	}
	rows := make([]explainRow, 0, len(shown)+1)
	for i, f := range shown {
		label := ""
		if i == 0 {
			label = "files"
		}
		rows = append(rows, explainRow{Label: label, Value: f})
	}
	if more > 0 {
		rows = append(rows, explainRow{Label: "", Value: fmt.Sprintf("… and %d more", more)})
	}
