// block reads as a child of the list row, and continuation rows align with
// values instead of jumping back to the left margin.
func overviewDetailBlock(sty statusStyles, rows []explainRow) string {
	width := 7
	for _, r := range rows {
		if l := len(r.Label); l > width {
			width = l
		}
	}
	var b strings.Builder
	for _, r := range rows {
		if r.Label == "" {
			fmt.Fprintf(&b, "    %s  %s\n", strings.Repeat(" ", width), r.Value)
			continue
		}
		paddedLabel := fmt.Sprintf("%-*s", width, r.Label)
		fmt.Fprintf(&b, "    %s  %s\n", sty.render(sty.dim, paddedLabel), r.Value)
	}
	return b.String()
}

// trailWebURL builds the entire.io web URL for a trail. Falls back to the
// repo's trails index when the trail has no number yet.
func trailWebURL(baseURL, forge, owner, repo string, number int) string {
	base := strings.TrimRight(baseURL, "/")
	if number > 0 {
		return fmt.Sprintf("%s/%s/%s/%s/trails/%d", base, forge, owner, repo, number)
	}
	return fmt.Sprintf("%s/%s/%s/%s/trails", base, forge, owner, repo)
}

