// renderOverview writes the full static overview. The TUI reuses the same
// row builders but assembles sections itself so it can track cursor rows.
func renderOverview(w io.Writer, sty statusStyles, data *overviewData, limit int) {
	fmt.Fprintln(w)
	fmt.Fprint(w, sty.identityBullet("Overview", overviewHeaderLabel(data)))
	fmt.Fprintln(w)

	fmt.Fprintln(w, sty.sectionRule("Sessions", sty.width))
	if len(data.Sessions) == 0 {
		fmt.Fprintln(w, sty.render(sty.dim, "  No sessions yet."))
	}
	for _, s := range limitSlice(data.Sessions, limit) {
		fmt.Fprintf(w, "  %s\n", overviewSessionRow(sty, s))
	}
	writeOverviewSectionFooter(w, sty, len(data.Sessions), limit, "entire session list")
	fmt.Fprintln(w)

	fmt.Fprintln(w, sty.sectionRule("Checkpoints", sty.width))
	if len(data.Checkpoints) == 0 {
		fmt.Fprintln(w, sty.render(sty.dim, "  No checkpoints yet."))
	}
	for _, c := range limitSlice(data.Checkpoints, limit) {
		fmt.Fprintf(w, "  %s\n", overviewCheckpointRow(sty, c))
	}
	writeOverviewSectionFooter(w, sty, len(data.Checkpoints), limit, "entire checkpoint list")
	fmt.Fprintln(w)

	fmt.Fprintln(w, sty.sectionRule("Trails", sty.width))
	switch {
	case data.TrailsErr != nil:
		fmt.Fprintln(w, sty.render(sty.dim, "  "+overviewTrailHint(data.TrailsErr)))
	case len(data.Trails) == 0:
		fmt.Fprintln(w, sty.render(sty.dim, "  No trails yet."))
	default:
		for _, t := range limitSlice(data.Trails, limit) {
			fmt.Fprintf(w, "  %s\n", overviewTrailRow(sty, t))
		}
		writeOverviewSectionFooter(w, sty, len(data.Trails), limit, "entire trail list")
	}
	fmt.Fprintln(w)
}

// overviewHeaderLabel returns "owner/repo (branch)" with whichever parts are known.
func overviewHeaderLabel(data *overviewData) string {
	label := data.RepoLabel
	if data.Branch != "" {
		if label != "" {
			return label + " (" + data.Branch + ")"
		}
		return data.Branch
	}
	return label
}

// writeOverviewSectionFooter writes a dim "shown of total · <hint>" line when
// the section was truncated by the limit.
func writeOverviewSectionFooter(w io.Writer, sty statusStyles, total, limit int, hint string) {
	if total <= limit {
		return
	}
	fmt.Fprintln(w, sty.render(sty.dim, fmt.Sprintf("  %d of %d · %s", limit, total, hint)))
}

