package cli

import (
	"fmt"
	"io"
	"strconv"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/trail"
)

const (
	overviewTitleMaxRunes  = 48
	overviewPromptMaxRunes = 200
	overviewMaxDetailFiles = 8
)

// renderOverview writes the full static overview. The TUI reuses the same
// row builders but assembles sections itself so it can track cursor rows.
func renderOverview(w io.Writer, sty statusStyles, data *overviewData, limit int) {
	fmt.Fprintln(w)
	fmt.Fprint(w, sty.identityBullet("Overview", overviewHeaderLabel(data)))
	fmt.Fprintln(w)

	fmt.Fprintln(w, sty.sectionRule("Sessions", sty.width))
	if len(data.Sessions) == 0 {
		fmt.Fprintln(w, sty.render(sty.dim, "  No sessions yet."))
	}
	for _, s := range limitSlice(data.Sessions, limit) {
		fmt.Fprintf(w, "  %s\n", overviewSessionRow(sty, s))
	}
	writeOverviewSectionFooter(w, sty, len(data.Sessions), limit, "entire session list")
	fmt.Fprintln(w)

	fmt.Fprintln(w, sty.sectionRule("Checkpoints", sty.width))
	if len(data.Checkpoints) == 0 {
		fmt.Fprintln(w, sty.render(sty.dim, "  No checkpoints yet."))
	}
	for _, c := range limitSlice(data.Checkpoints, limit) {
		fmt.Fprintf(w, "  %s\n", overviewCheckpointRow(sty, c))
	}
	writeOverviewSectionFooter(w, sty, len(data.Checkpoints), limit, "entire checkpoint list")
	fmt.Fprintln(w)

	fmt.Fprintln(w, sty.sectionRule("Trails", sty.width))
	switch {
	case data.TrailsErr != nil:
		fmt.Fprintln(w, sty.render(sty.dim, "  "+overviewTrailHint(data.TrailsErr)))
	case len(data.Trails) == 0:
		fmt.Fprintln(w, sty.render(sty.dim, "  No trails yet."))
	default:
		for _, t := range limitSlice(data.Trails, limit) {
			fmt.Fprintf(w, "  %s\n", overviewTrailRow(sty, t))
		}
		writeOverviewSectionFooter(w, sty, len(data.Trails), limit, "entire trail list")
	}
	fmt.Fprintln(w)
}

// overviewHeaderLabel returns "owner/repo (branch)" with whichever parts are known.
func overviewHeaderLabel(data *overviewData) string {
	label := data.RepoLabel
	if data.Branch != "" {
		if label != "" {
			return label + " (" + data.Branch + ")"
		}
		return data.Branch
	}
	return label
}

// writeOverviewSectionFooter writes a dim "shown of total · <hint>" line when
// the section was truncated by the limit.
func writeOverviewSectionFooter(w io.Writer, sty statusStyles, total, limit int, hint string) {
	if total <= limit {
		return
	}
	fmt.Fprintln(w, sty.render(sty.dim, fmt.Sprintf("  %d of %d · %s", limit, total, hint)))
}

// overviewSessionRow renders one session as a single line:
// ● status  "prompt…"  agent · 22m ago
func overviewSessionRow(sty statusStyles, s *strategy.SessionState) string {
	status := sessionPhaseLabel(s)
	bullet := sty.render(sty.dim, "○")
	if s.EndedAt == nil {
		bullet = sty.render(sty.green, "●")
	}

	agentLabel := string(s.AgentType)
	if agentLabel == "" {
		agentLabel = unknownPlaceholder
	}

	title := "(no prompt)"
	if s.LastPrompt != "" {
		title = truncateOneLine(s.LastPrompt, overviewTitleMaxRunes)
	}

	sep := sty.render(sty.dim, " · ")
	meta := sty.render(sty.agent, agentLabel) + sep + sty.render(sty.dim, timeAgo(sessionLastActivity(s)))
	return fmt.Sprintf("%s %s  %s  %s", bullet, sty.render(sty.dim, fmt.Sprintf("%-7s", status)), title, meta)
}

// overviewCheckpointRow renders one checkpoint as a single line:
// a1b2c3d4e5f6  Fix login flow  3 files · claude · 2h ago
func overviewCheckpointRow(sty statusStyles, c overviewCheckpoint) string {
	idLabel := sty.render(sty.cyan, c.CheckpointID.String())

	title := truncateOneLine(c.CommitSubject, overviewTitleMaxRunes)
	if title == "" {
		title = "(no commit message)"
	}

	parts := []string{strconv.Itoa(len(c.FilesTouched)) + " " + pluralize("file", len(c.FilesTouched))}
	if c.Agent != "" {
		parts = append(parts, string(c.Agent))
	}
	if c.SessionCount > 1 {
		parts = append(parts, fmt.Sprintf("%d sessions", c.SessionCount))
	}
	if c.IsTask {
		parts = append(parts, "task")
	}
	parts = append(parts, timeAgo(c.CreatedAt))
	return fmt.Sprintf("%s  %s  %s", idLabel, title, sty.render(sty.dim, strings.Join(parts, " · ")))
}

// overviewTrailRow renders one trail as a single line:
// #12  Add overview command  in_progress · branch · 1d ago
// showAuthor adds the author login, used when trails couldn't be filtered to
// the current user.
func overviewTrailRow(sty statusStyles, t *trail.Metadata, showAuthor bool) string {
	number := "—"
	if t.Number > 0 {
		number = "#" + strconv.Itoa(t.Number)
	}
	title := truncateOneLine(t.Title, overviewTitleMaxRunes)
	if title == "" {
		title = "(untitled)"
	}
	meta := []string{string(t.Status)}
	if t.Branch != "" {
		meta = append(meta, t.Branch)
	}
	if showAuthor {
		if login := t.AuthorLogin(); login != "" {
			meta = append(meta, login)
		}
	}
	meta = append(meta, timeAgo(t.UpdatedAt))
	return fmt.Sprintf("%s  %s  %s", sty.render(sty.cyan, number), title, sty.render(sty.dim, strings.Join(meta, " · ")))
}

// overviewSessionDetail renders the expanded inline block for a session.
// Everything comes from the already-loaded session state.
func overviewSessionDetail(sty statusStyles, s *strategy.SessionState) string {
	rows := []explainRow{
		{Label: "session", Value: s.SessionID},
		{Label: "worktree", Value: sessionWorktreeLabel(s)},
	}
	if s.ModelName != "" {
		rows = append(rows, explainRow{Label: "model", Value: s.ModelName})
	}
	rows = append(rows, explainRow{Label: "started", Value: s.StartedAt.Local().Format("2006-01-02 15:04") + " (" + timeAgo(s.StartedAt) + ")"})
	if s.SessionTurnCount > 0 {
		rows = append(rows, explainRow{Label: "turns", Value: strconv.Itoa(s.SessionTurnCount)})
	}
	if t := totalTokens(s.TokenUsage); t > 0 {
		rows = append(rows, explainRow{Label: "tokens", Value: formatTokenCount(t)})
	}
	if s.LastCheckpointID != "" {
		rows = append(rows, explainRow{Label: "checkpoint", Value: string(s.LastCheckpointID)})
	}
	if s.LastPrompt != "" {
		rows = append(rows, explainRow{Label: "prompt", Value: strconv.Quote(truncateOneLine(s.LastPrompt, overviewPromptMaxRunes))})
	}
	rows = append(rows, overviewFilesRows(s.FilesTouched)...)
	return overviewDetailBlock(sty, rows)
}

// overviewCheckpointDetail renders the expanded inline block for a checkpoint.
// summary is the lazily-loaded committed metadata; nil while loading or on error.
func overviewCheckpointDetail(sty statusStyles, c strategy.CheckpointInfo, summary *checkpoint.CheckpointSummary, loadErr error, loading bool) string {
	rows := []explainRow{
		{Label: "created", Value: c.CreatedAt.Local().Format("2006-01-02 15:04") + " (" + timeAgo(c.CreatedAt) + ")"},
	}
	if len(c.SessionIDs) > 0 {
		rows = append(rows, explainRow{Label: "sessions", Value: strings.Join(c.SessionIDs, ", ")})
	} else if c.SessionID != "" {
		rows = append(rows, explainRow{Label: "session", Value: c.SessionID})
	}
	switch {
	case loading:
		rows = append(rows, explainRow{Label: "details", Value: "loading…"})
	case loadErr != nil:
		rows = append(rows, explainRow{Label: "details", Value: "unavailable: " + loadErr.Error()})
	case summary != nil:
		if summary.Branch != "" {
			rows = append(rows, explainRow{Label: "branch", Value: summary.Branch})
		}
		if t := totalTokens(summary.TokenUsage); t > 0 {
			rows = append(rows, explainRow{Label: "tokens", Value: formatTokenCount(t)})
		}
		if summary.HasReview {
			rows = append(rows, explainRow{Label: "reviewed", Value: "yes"})
		}
	}
	rows = append(rows, overviewFilesRows(c.FilesTouched)...)
	rows = append(rows, explainRow{Label: "explain", Value: "entire checkpoint explain " + c.CheckpointID.String()})
	return overviewDetailBlock(sty, rows)
}

// overviewFilesRows renders a capped files-touched list: a "files" row with
// the first path, then unlabeled continuation rows.
func overviewFilesRows(files []string) []explainRow {
	if len(files) == 0 {
		return nil
	}
	shown := files
	more := 0
	if len(shown) > overviewMaxDetailFiles {
		more = len(shown) - overviewMaxDetailFiles
		shown = shown[:overviewMaxDetailFiles]
	}
	rows := make([]explainRow, 0, len(shown)+1)
	for i, f := range shown {
		label := ""
		if i == 0 {
			label = "files"
		}
		rows = append(rows, explainRow{Label: label, Value: f})
	}
	if more > 0 {
		rows = append(rows, explainRow{Label: "", Value: fmt.Sprintf("… and %d more", more)})
	}
	return rows
}

// overviewDetailBlock renders label/value rows as an indented block beneath a
// row. Mirrors statusStyles.metadataRows but with a deeper indent so the
// block reads as a child of the list row, and continuation rows align with
// values instead of jumping back to the left margin.
func overviewDetailBlock(sty statusStyles, rows []explainRow) string {
	width := 7
	for _, r := range rows {
		if l := len(r.Label); l > width {
			width = l
		}
	}
	var b strings.Builder
	for _, r := range rows {
		if r.Label == "" {
			fmt.Fprintf(&b, "    %s  %s\n", strings.Repeat(" ", width), r.Value)
			continue
		}
		paddedLabel := fmt.Sprintf("%-*s", width, r.Label)
		fmt.Fprintf(&b, "    %s  %s\n", sty.render(sty.dim, paddedLabel), r.Value)
	}
	return b.String()
}

// trailWebURL builds the entire.io web URL for a trail. Falls back to the
// repo's trails index when the trail has no number yet.
func trailWebURL(baseURL, forge, owner, repo string, number int) string {
	base := strings.TrimRight(baseURL, "/")
	if number > 0 {
		return fmt.Sprintf("%s/%s/%s/%s/trails/%d", base, forge, owner, repo, number)
	}
	return fmt.Sprintf("%s/%s/%s/%s/trails", base, forge, owner, repo)
}

