// assignOverviewSessions distributes sessions into trail groups. A session
// belongs to a trail when it contributed to one of the trail's checkpoints
// (by session ID or last-checkpoint link), or — for sessions with no
// committed checkpoint yet — when its worktree is on the trail's branch.
// Everything else goes to the unassigned bucket. branchOf resolves a
// session's worktree branch and is injected for testability.
func assignOverviewSessions(groups []overviewGroup, unassigned *overviewGroup, sessions []*strategy.SessionState, branchOf func(*strategy.SessionState) string) {
	bySessionID := make(map[string]int)
	byCheckpointID := make(map[id.CheckpointID]int)
	byBranch := make(map[string]int)
	for gi := range groups {
		for _, cp := range groups[gi].Checkpoints {
			byCheckpointID[cp.CheckpointID] = gi
			for _, sid := range cp.SessionIDs {
				if _, taken := bySessionID[sid]; !taken {
					bySessionID[sid] = gi
				}
			}
		}
		if groups[gi].Trail != nil && groups[gi].Trail.Branch != "" {
			if _, taken := byBranch[groups[gi].Trail.Branch]; !taken {
				byBranch[groups[gi].Trail.Branch] = gi
			}
		}
	}

	for _, s := range sessions {
		gi, ok := bySessionID[s.SessionID]
		if !ok {
			gi, ok = byCheckpointID[s.LastCheckpointID]
		}
		if !ok {
			if branch := branchOf(s); branch != "" {
				gi, ok = byBranch[branch]
			}
		}
		if ok {
			groups[gi].Sessions = append(groups[gi].Sessions, s)
		} else {
			unassigned.Sessions = append(unassigned.Sessions, s)
		}
	}
