// overviewWorktreeBranch resolves the branch a session's worktree is
// currently on, caching per path. Best-effort: deleted worktrees or detached
// HEADs resolve to "".
func overviewWorktreeBranch(cache map[string]string, s *strategy.SessionState) string {
	path := s.WorktreePath
	if path == "" {
		return ""
	}
	if branch, ok := cache[path]; ok {
		return branch
	}
	branch := ""
	if repo, err := git.PlainOpen(path); err == nil {
		if head, headErr := repo.Head(); headErr == nil && head.Name().IsBranch() {
			branch = head.Name().Short()
		}
	}
	cache[path] = branch
	return branch
}

