// renderOverview writes the full static overview: one block per trail with
// its sessions and checkpoints nested under it, then the unassigned bucket.
// The TUI reuses the same row builders but assembles the body itself so it
// can track cursor rows.
func renderOverview(w io.Writer, sty statusStyles, data *overviewData, limit int) {
	fmt.Fprintln(w)
	fmt.Fprint(w, sty.identityBullet("Overview", overviewHeaderLabel(data)))
	fmt.Fprintln(w)

	if len(data.Groups) == 0 {
		renderOverviewFlat(w, sty, data, limit)
		return
	}

	if data.TrailsAuthor == "" {
		fmt.Fprintln(w, sty.render(sty.dim, "  "+overviewTrailsAllAuthorsNote))
		fmt.Fprintln(w)
	}
	for _, g := range data.Groups {
		fmt.Fprintf(w, "%s\n", overviewTrailRow(sty, g.Trail, data.TrailsAuthor == ""))
		renderOverviewGroupBody(w, sty, g, limit)
		fmt.Fprintln(w)
	}
	if data.TrailsTotal > len(data.Groups) {
		fmt.Fprintln(w, sty.render(sty.dim, fmt.Sprintf("%d of %d trails · entire trail list", len(data.Groups), data.TrailsTotal)))
		fmt.Fprintln(w)
	}

	if len(data.Unassigned.Sessions) > 0 || len(data.Unassigned.Checkpoints) > 0 {
		fmt.Fprintln(w, sty.sectionRule(overviewUnassignedTitle, sty.width))
		renderOverviewGroupBody(w, sty, data.Unassigned, limit)
		fmt.Fprintln(w)
	}
}

// overviewUnassignedTitle heads the bucket for work not attached to a trail.
const overviewUnassignedTitle = "Not on a trail"

// renderOverviewGroupBody writes the nested Sessions/Checkpoints sub-blocks
// of one group.
func renderOverviewGroupBody(w io.Writer, sty statusStyles, g overviewGroup, limit int) {
	if len(g.Sessions) == 0 && len(g.Checkpoints) == 0 {
		fmt.Fprintln(w, sty.render(sty.dim, "    No local sessions or checkpoints."))
		return
	}
	if len(g.Sessions) > 0 {
		fmt.Fprintln(w, sty.render(sty.dim, "    Sessions"))
		for _, s := range limitSlice(g.Sessions, limit) {
			fmt.Fprintf(w, "      %s\n", overviewSessionRow(sty, s))
		}
		writeOverviewGroupFooter(w, sty, len(g.Sessions), limit, "entire session list")
	}
	if len(g.Checkpoints) > 0 {
		fmt.Fprintln(w, sty.render(sty.dim, "    Checkpoints"))
		for _, c := range limitSlice(g.Checkpoints, limit) {
			fmt.Fprintf(w, "      %s\n", overviewCheckpointRow(sty, c))
		}
		writeOverviewGroupFooter(w, sty, len(g.Checkpoints), limit, "entire checkpoint list")
	}
}

// writeOverviewGroupFooter writes a dim "shown of total · <hint>" line at the
// nested indent when a sub-block was truncated by the limit.
func writeOverviewGroupFooter(w io.Writer, sty statusStyles, total, limit int, hint string) {
	if total <= limit {
		return
	}
	fmt.Fprintln(w, sty.render(sty.dim, fmt.Sprintf("      %d of %d · %s", limit, total, hint)))
}

// renderOverviewFlat is the layout when there are no trail groups (trails
// unavailable, or none for this user): flat Sessions and Checkpoints
