	fmt.Fprintln(w, sty.sectionRule("Checkpoints", sty.width))
	if len(data.Unassigned.Checkpoints) == 0 {
		fmt.Fprintln(w, sty.render(sty.dim, "  No checkpoints yet."))
	}
	for _, c := range limitSlice(data.Unassigned.Checkpoints, limit) {
		fmt.Fprintf(w, "  %s\n", overviewCheckpointRow(sty, c))
	}
	writeOverviewSectionFooter(w, sty, len(data.Unassigned.Checkpoints), limit, "entire checkpoint list")
	fmt.Fprintln(w)

	fmt.Fprintln(w, sty.sectionRule("Trails", sty.width))
	if data.TrailsErr != nil {
		fmt.Fprintln(w, sty.render(sty.dim, "  "+overviewTrailHint(data.TrailsErr)))
	} else {
		fmt.Fprintln(w, sty.render(sty.dim, "  "+overviewNoTrailsLabel(data.TrailsAuthor)))
	}
