// overviewSection identifies which list a cursor row belongs to.
type overviewSection int

const (
	overviewSectionSessions overviewSection = iota
	overviewSectionCheckpoints
	overviewSectionTrails
)

// overviewRowRef points at one selectable row in the flattened row list.
type overviewRowRef struct {
	section overviewSection
	index   int // index into the section's (already limited) slice
}

// overviewKeys extends the shared keyMap with overview-only bindings.
var overviewKeys = struct {
	Resume  key.Binding
	NextSec key.Binding
}{
	Resume: key.NewBinding(
		key.WithKeys("r"),
		key.WithHelp("r", "resume"),
	),
	NextSec: key.NewBinding(
		key.WithKeys("tab"),
		key.WithHelp("tab", "next section"),
	),
