// then its (limited) sessions and checkpoints, then the unassigned bucket's
// rows.
func buildOverviewRows(data *overviewData, limit int) []overviewRowRef {
	var rows []overviewRowRef
	appendGroup := func(gi int, g overviewGroup) {
		if g.Trail != nil {
			rows = append(rows, overviewRowRef{group: gi, section: overviewSectionTrails})
		}
		for i := range limitSlice(g.Sessions, limit) {
			rows = append(rows, overviewRowRef{group: gi, section: overviewSectionSessions, index: i})
		}
		for i := range limitSlice(g.Checkpoints, limit) {
			rows = append(rows, overviewRowRef{group: gi, section: overviewSectionCheckpoints, index: i})
		}
	}
