// renderBody renders the trail groups and the unassigned bucket, returning
// the content plus, for each cursor row, the line index it starts at (for
// scroll-into-view). Mirrors renderOverview's static layout.
func (m overviewModel) renderBody() (string, []int) {
	var b strings.Builder
	rowLines := make([]int, 0, len(m.rows))
	line := 0
	write := func(s string) {
		b.WriteString(s)
		line += strings.Count(s, "\n")
	}

	rowIdx := 0
	// writeRow emits one selectable row. indent is the static prefix before
	// the cursor marker (nested rows sit deeper than trail headers).
	writeRow := func(indent, content, expandedDetail string) {
		marker := "  "
		if rowIdx == m.cursor {
			marker = m.sty.render(m.sty.agent, "▸") + " "
		}
		rowLines = append(rowLines, line)
		write(indent + marker + content + "\n")
		if m.expanded[rowIdx] && expandedDetail != "" {
			write(expandedDetail)
		}
		rowIdx++
	}

	writeGroupBody := func(g overviewGroup, indent string) {
		if len(g.Sessions) == 0 && len(g.Checkpoints) == 0 {
			write(m.sty.render(m.sty.dim, indent+"  No local sessions or checkpoints.") + "\n")
			return
		}
		if len(g.Sessions) > 0 {
			write(m.sty.render(m.sty.dim, indent+"  Sessions") + "\n")
			for _, s := range limitSlice(g.Sessions, m.opts.Limit) {
				detail := ""
				if m.expanded[rowIdx] {
					detail = overviewSessionDetail(m.sty, s)
				}
				writeRow(indent+"  ", overviewSessionRow(m.sty, s), detail)
			}
			m.writeGroupFooter(write, indent, len(g.Sessions), "entire session list")
		}
		if len(g.Checkpoints) > 0 {
			write(m.sty.render(m.sty.dim, indent+"  Checkpoints") + "\n")
			for _, c := range limitSlice(g.Checkpoints, m.opts.Limit) {
				detail := ""
				if m.expanded[rowIdx] {
					st := m.cpDetails[c.CheckpointID]
					if st == nil {
						st = &overviewCheckpointDetailState{loading: true}
					}
					detail = overviewCheckpointDetail(m.sty, c, st.summary, st.err, st.loading)
				}
				writeRow(indent+"  ", overviewCheckpointRow(m.sty, c), detail)
			}
			m.writeGroupFooter(write, indent, len(g.Checkpoints), "entire checkpoint list")
		}
	}

	if len(m.data.Groups) == 0 {
		// Flat layout: no trail groups (trails unavailable or none).
		write(m.sty.sectionRule("Sessions", m.sty.width) + "\n")
		if len(m.data.Unassigned.Sessions) == 0 {
			write(m.sty.render(m.sty.dim, "  No sessions yet.") + "\n")
		}
		for _, s := range limitSlice(m.data.Unassigned.Sessions, m.opts.Limit) {
			detail := ""
			if m.expanded[rowIdx] {
				detail = overviewSessionDetail(m.sty, s)
			}
			writeRow("", overviewSessionRow(m.sty, s), detail)
		}
		m.writeGroupFooter(write, "", len(m.data.Unassigned.Sessions), "entire session list")
		write("\n")

		write(m.sty.sectionRule("Checkpoints", m.sty.width) + "\n")
		if len(m.data.Unassigned.Checkpoints) == 0 {
			write(m.sty.render(m.sty.dim, "  No checkpoints yet.") + "\n")
		}
		for _, c := range limitSlice(m.data.Unassigned.Checkpoints, m.opts.Limit) {
			detail := ""
			if m.expanded[rowIdx] {
				st := m.cpDetails[c.CheckpointID]
				if st == nil {
					st = &overviewCheckpointDetailState{loading: true}
				}
				detail = overviewCheckpointDetail(m.sty, c, st.summary, st.err, st.loading)
			}
			writeRow("", overviewCheckpointRow(m.sty, c), detail)
		}
		m.writeGroupFooter(write, "", len(m.data.Unassigned.Checkpoints), "entire checkpoint list")
		write("\n")

		write(m.sty.sectionRule("Trails", m.sty.width) + "\n")
		if m.data.TrailsErr != nil {
			write(m.sty.render(m.sty.dim, "  "+overviewTrailHint(m.data.TrailsErr)) + "\n")
		} else {
			write(m.sty.render(m.sty.dim, "  "+overviewNoTrailsLabel(m.data.TrailsAuthor)) + "\n")
		}
		return b.String(), rowLines
	}

	if m.data.TrailsAuthor == "" {
		write(m.sty.render(m.sty.dim, "  "+overviewTrailsAllAuthorsNote) + "\n\n")
	}
	for _, g := range m.data.Groups {
		writeRow("", overviewTrailRow(m.sty, g.Trail, m.data.TrailsAuthor == ""), "")
		writeGroupBody(g, "    ")
		write("\n")
	}
	if m.data.TrailsTotal > len(m.data.Groups) {
		write(m.sty.render(m.sty.dim, fmt.Sprintf("%d of %d trails · entire trail list", len(m.data.Groups), m.data.TrailsTotal)) + "\n\n")
	}

	if len(m.data.Unassigned.Sessions) > 0 || len(m.data.Unassigned.Checkpoints) > 0 {
		write(m.sty.sectionRule(overviewUnassignedTitle, m.sty.width) + "\n")
		writeGroupBody(m.data.Unassigned, "")
	}

	return b.String(), rowLines
}

// writeGroupFooter writes a dim "shown of total · <hint>" line at the given
// indent when a sub-block was truncated by the limit.
func (m overviewModel) writeGroupFooter(write func(string), indent string, total int, hint string) {
	if total <= m.opts.Limit {
		return
	}
	write(m.sty.render(m.sty.dim, fmt.Sprintf("%s  %d of %d · %s", indent, m.opts.Limit, total, hint)) + "\n")
}

