func TestFetchOverviewData_LocalOnly(t *testing.T) {
	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "f.txt", "init")
	testutil.GitAdd(t, tmpDir, "f.txt")
	testutil.GitCommit(t, tmpDir, "init")
	t.Chdir(tmpDir)

	data, err := fetchOverviewData(context.Background(), overviewOptions{Limit: 5})
	if err != nil {
		t.Fatalf("fetchOverviewData: %v", err)
	}

	if len(data.Sessions) != 0 {
		t.Errorf("expected no sessions, got %d", len(data.Sessions))
	}
	if len(data.Checkpoints) != 0 {
		t.Errorf("expected no checkpoints, got %d", len(data.Checkpoints))
	}
	if data.TrailsErr == nil {
		t.Error("expected TrailsErr for repo without forge remote")
	}
	if data.Branch == "" {
		t.Error("expected current branch to resolve")
	}
	if data.RepoLabel == "" {
		t.Error("expected repo label fallback to worktree dir name")
	}
}

// TestRunOverview_JSONInTempRepo exercises the command path end to end in
